    qarabag_video_title_1: "Летопись Победы · 8 Ноября",
    qarabag_video_badge_1: "КАРАБАХ — ЭТО АЗЕРБАЙДЖАН!",
    qarabag_cinema_btn_1: "Летопись Победы (Полный экран)",
