let currentLang = "az";

function gT(key) {
  return i18n[currentLang][key] || key;
}

function updateDOMTexts() {
  // Icon-safe innerHTML/text translation
  document.querySelectorAll("[data-i18n]").forEach((el) => {
    const key = el.getAttribute("data-i18n");
    const val = i18n[currentLang] && i18n[currentLang][key];
    if (!val) return;

    // If element wraps an icon/svg alongside a separate text span or child span with same/nested structure
    const hasIconChild = el.querySelector(":scope > svg, :scope > .badge-icon, :scope > .mobile-nav-icon");
    if (hasIconChild && !val.includes("<span") && !val.includes("<br")) {
      const innerTextSpan = Array.from(el.children).find(
        (c) => c.tagName === "SPAN" && !c.classList.contains("badge-icon") && !c.classList.contains("mobile-nav-icon")
      );
      if (innerTextSpan) {
        if (!innerTextSpan.hasAttribute("data-i18n")) {
          innerTextSpan.textContent = val;
        }
        return;
      }
      // Remove only loose text nodes and append translated text node after icon
      Array.from(el.childNodes).forEach((node) => {
        if (node.nodeType === Node.TEXT_NODE) {
          node.remove();
        }
      });
      el.appendChild(document.createTextNode(" " + val));
      return;
    }

    el.innerHTML = val;
  });

  // Placeholder translations
  document.querySelectorAll("[data-i18n-placeholder]").forEach((el) => {
    const key = el.getAttribute("data-i18n-placeholder");
    if (i18n[currentLang] && i18n[currentLang][key]) {
      el.placeholder = i18n[currentLang][key];
    }
  });

  // Title / Tooltip translations
  document.querySelectorAll("[data-i18n-title]").forEach((el) => {
    const key = el.getAttribute("data-i18n-title");
    if (i18n[currentLang] && i18n[currentLang][key]) {
      el.title = i18n[currentLang][key];
      if (!el.hasAttribute("data-i18n-aria") && !el.getAttribute("aria-label")) {
        el.setAttribute("aria-label", i18n[currentLang][key]);
      }
    }
  });

  // Aria-label translations
  document.querySelectorAll("[data-i18n-aria]").forEach((el) => {
    const key = el.getAttribute("data-i18n-aria");
    if (i18n[currentLang] && i18n[currentLang][key]) {
      el.setAttribute("aria-label", i18n[currentLang][key]);
    }
  });

  // Categories Sub-labels update explicitly (since they generated dynamically later sometimes)
  renderCategoriesCount();

  // Rerender active module texts
  if (typeof window.renderCertificatesGrid === "function") {
    window.renderCertificatesGrid();
  }
  if (typeof window.renderScienceAuthors === "function") {
    window.renderScienceAuthors();
  }

  const sisDash = document.getElementById("sis-dashboard");
  if (
    sisDash &&
    sisDash.style.display === "block" &&
    typeof currentGroup !== "undefined" &&
    currentGroup
  ) {
    renderGroupDashboard(currentGroup, activeSemester, activeSubject);
  }
}

