newsData.sort((a, b) => {
  const months = {
    yanvar: 1, fevral: 2, mart: 3, aprel: 4, may: 5, iyun: 6,
    iyul: 7, avqust: 8, sentyabr: 9, oktyabr: 10, noyabr: 11, dekabr: 12,
  };
  const toKey = (item) => {
    const s = String(item?.date || "").trim().toLowerCase().replace(/i\u0307/g, "i").replace(/\u0131/g, "i");
    const m = s.match(/^(?:(\d{1,2})\s+)?([a-zəöüöğçş]+)\s+(\d{4})$/);
    if (!m) return 0;
    const day = m[1] ? parseInt(m[1], 10) : 1;
    const mon = months[m[2]] || 0;
    const year = parseInt(m[3], 10);
    return year * 10000 + mon * 100 + day;
  };
  return toKey(b) - toKey(a);
});


